head.script:
// 화면 리사이징

scwin.gAcptNo;
scwin.gIsurCd;

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
    scwin.gform_onload();
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name setCode
 * @description set Code 처리
 * @returns {void}
 * @hidden N
 */
scwin.setCode = function() {
    if (js_market === "1" || js_market === "2" || js_market === "6") {
        rdo_MARKET_TP_CD.setValue(js_market);
    }

    //  기간 from~ to  셋팅
    vCurDate = $c.ut.cGetToday("yyyymmdd");

    // edt_FromDate.text = '20130101';     // 현재날짜
    edt_ToDate.setValue(vCurDate); // 현재날짜
    $c.stf.setFromToDate(5, edt_FromDate, edt_ToDate); // 일년전 날짜

    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************

};X < !공시상세--;
목록검색;
클릭-- > async function() {
    const vFormCd = txb_FormCd.getValue();
    const vFormNm = txb_FormNm.getValue();

    // 일자 체크
    if (edt_FromDate.getValue().length < 8) {
        await $c.win.alert("일자 올바르게 입력하십시오.");
        edt_FromDate.focus();
        return;
    }

    // 일자 체크
    if (edt_ToDate.getValue().length < 8) {
        await $c.win.alert("일자 올바르게 입력하십시오.");
        edt_ToDate.focus();
        return;
    }
    if ($c.stf.compareFromToDate2(edt_FromDate, edt_ToDate) === false) {
        return;
    }

    // 보고서코그 체크
    /*if (vFormCd.length >0 && vFormCd.length != 5) {
    	alert("보고서코드 5자리를 입력하십시오." );
    	txb_FormCd.focus();
    	return;
    }*/

    fn_Search();
} < !공시상세--;
클릭-- > async function() {
    // alert(url_cond);

    const sbmOptions = {
        id : "sbm_dts_DsclList",
        action : "/DisclosureSearch.do",
        ref : "",
        target : "dts_DsclList=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
     * @method
     * @name getChkValue
     * @description get Chk Value 처리
     * @param {Object} obj 컴포넌트
     * @returns {void}
     * @hidden N
     */
scwin.getChkValue = function(obj) {
    // return (obj.checked) ? "Y" : "N";
    if (obj.checked === true) {
        return obj.getValue();
    } else {
        return "";
    }
};

/**
 * @method
 * @name setContnId
 * @description 그리드에서 클릭 row의 변수셋팅
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.setContnId = function(obj) {
    scwin.gAcptNo = dts_DsclList.getCellData(Number(obj), "ACPT_NO");
};

/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Search_onclick = function() {
    fn_CheckCond();
};

/**
 * @method
 * @name dts_DsclList_OnLoadError
 * @description dts_DsclList 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_DsclList_OnLoadError = async function() {
    await $c.win.alert("OnLoadError => " + dts_DsclList);
};

/**
 * @method
 * @name dts_DsclList_OnLoadCompleted
 * @description dts_DsclList 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_DsclList_OnLoadCompleted = async function(rowcount) {
    if (dts_DsclList.errorMsg) {
        await $c.win.alert("OnLoadCompleted => " + dts_DsclList.errorMsg);
    } else {
        $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page);
    }
};

/**
 * @method
 * @name grd_Grid_OnDblClick
 * @description 클릭된 값 변수에 셋팅
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_Grid_OnDblClick = async function(row, colid) {
    // 클릭된 값 변수에 셋팅
    scwin.setContnId(row);
    if (colid === "DOC_TITLE") {
        await $c.stf.openDisclViewer(scwin.gAcptNo, "R");
    }
};

/**
 * @method
 * @name img_FromCal_onclick
 * @description img_FromCal 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_FromCal_onclick = function() {
    popUpCalendar2(edt_FromDate);
};

/**
 * @method
 * @name img_ToCal_onclick
 * @description img_ToCal 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_ToCal_onclick = function() {
    popUpCalendar2(edt_ToDate);
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_onclick = function() {
    $c.data.downloadGridViewExcel(grd_Grid, {fileName: "기타법인 공시상세검색  목록", type: "8"});
};

/**
 * @method
 * @name img_FindForm_onclick
 * @description *** 셋팅할 필드명 정의를 아래처럼 해야함.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_FindForm_onclick = async function() {
    // *** 셋팅할 필드명 정의를 아래처럼 해야함.
    // => 보고서명: txb_FormNm, 보고서코드 : txb_FormCd
    const url = "/common/ULDSTF91003_ETC.gfm";
    const winTitle = "공시제목선택 ";
    await $c.frame.CreateDialogFrame("FORMLIST", url, winTitle, 100, 10, 690, 570, "window");
};

/**
 * @method
 * @name txb_FormCd_onblur
 * @description txb_FormCd 포커스 이탈 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_FormCd_onblur = function() {
    if (txb_FormCd.getValue() === "") {
        txb_FormNm.setValue("");
    }
};

/**
 * @method
 * @name txb_FormNm_onblur
 * @description txb_FormNm 포커스 이탈 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_FormNm_onblur = function() {
    if (txb_FormNm.getValue() === "") {
        txb_FormCd.setValue("");
    }
};

/**
 * @method
 * @name cmb_PeriodTp_onselchange
 * @description cmb_PeriodTp onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_PeriodTp_onselchange = function() {
    const vTp = $c.cp.valueOfIndex(cmb_PeriodTp, "VALUE", cmb_PeriodTp.getSelectedIndex());
    $c.stf.setFromToDate(vTp, edt_FromDate, edt_ToDate);
};

/**
 * @method
 * @name gform_onload
 * @description 패널라운드 처리
 * @returns {void}
 * @hidden N
 */
scwin.gform_onload = function() {
    // 패널라운드 처리
    $c.cm.PanelToGroupBox(panel_1);

    // 필요없는부분
    label_7.hide();
    txb_FormCd.hide();
    label_22.hide();
    txb_FormNm.hide();
    img_FindForm.hide();
    scwin.setCode();
    $c.stf.comboCbDataSetPeriod(cmb_PeriodTp);
    $c.cm.fn_com_isur(txb_isur_cd, txb_com_abbrv);
    fn_CheckCond();
};

/**
 * @method
 * @name img_com_srch_onclick
 * @description img_com_srch 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_com_srch_onclick = function() {
    $c.cm.IsurcdSearch(txb_isur_cd, txb_com_abbrv);
};

/**
 * @method
 * @name MxDataSet_com_isur_OnFilter
 * @description Mx Data Set com isur On Filter 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    if (skw !== "" && foColum === "1") {
        f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
        f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
        if (f1.indexOf(skw) !== -1 || f2.indexOf(skw) !== -1) return true;

        else return false;
    } else {
        return true;
    }
};

/**
 * @method
 * @name Grd_com_isur_OnKeyPress
 * @description Grd com isur On Key Press 처리
 * @param {*} kcode kcode
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    if (kcode === '13') {
        $c.cm.fn_com_Confirm_set();
    }
};

/**
 * @method
 * @name Grd_com_isur_OnDblClick
 * @description Grd_com_isur 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    $c.cm.fn_com_Confirm_set();
};

/**
 * @method
 * @name Grd_com_isur_OnClick
 * @description Grd_com_isur 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnClick = function(row, colid) {
    Grd_com_isur.style.display = "";
};

/**
 * @method
 * @name Grd_com_isur_OnSetFocus
 * @description Grd com isur On Set Focus 처리
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnSetFocus = function() {
    stFocusGrid = true;
};

/**
 * @method
 * @name Grd_com_isur_OnKillFocus
 * @description Grd_com_isur 포커스 이탈 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnKillFocus = function() {
    stFocusGrid = false;
    Grd_com_isur.style.display = "none";
};

/**
 * @method
 * @name txb_isur_cd_onblur
 * @description txb_isur_cd 포커스 이탈 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_isur_cd_onblur = function() {
    if (stFocusGrid === false) {
        Grd_com_isur.style.display = "none";
    }
    if (txb_isur_cd.getValue() === "") {
        txb_com_abbrv.setValue("");
    }
};

/**
 * @method
 * @name txb_isur_cd_onfocus
 * @description txb_isur_cd 포커스 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_isur_cd_onfocus = function() {
    Grd_com_isur.style.display = "none";
};

/**
 * @method
 * @name txb_isur_cd_onkeyup
 * @description txb_isur_cd 키 입력 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_isur_cd_onkeyup = function() {
    if (txb_isur_cd.getValue() === "") {
        Grd_com_isur.style.display = "none";
    } else {
        if (window.event.keyCode === 40) {
            // 아래화살표눌렀을때 그리드로 포커스
            Grd_com_isur.focus();
        } else {
            $c.cm.fn_com_isur_nm(window.event.keyCode);
        }
    }
};
